changeSet.sql:
ALTER TABLE zc_domain_audit
  ADD CONSTRAINT fk_zc_domain_audit_tenant FOREIGN KEY (tenant_id) REFERENCES zc_tenant (id);
ALTER TABLE zc_domain_audit
  ADD CONSTRAINT fk_zc_domain_audit_organisation FOREIGN KEY (tenant_id, organisation_id)
    REFERENCES zc_organisation (tenant_id, id);
ALTER TABLE zc_domain_audit
  ADD CONSTRAINT fk_zc_domain_audit_member FOREIGN KEY (tenant_id, member_id)
    REFERENCES zc_member_reference (tenant_id, id);
ALTER TABLE zc_domain_audit
  ADD CONSTRAINT fk_zc_domain_audit_programme_version FOREIGN KEY (tenant_id, programme_version_id)
    REFERENCES zc_programme_version (tenant_id, id);

-- Tenant isolation. The app must connect as zc_app: superusers bypass RLS.
ALTER TABLE zc_domain_audit ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_domain_audit FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_domain_audit_tenant ON zc_domain_audit
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());

rollback.sql:
DROP POLICY rls_zc_domain_audit_tenant ON zc_domain_audit;
ALTER TABLE zc_domain_audit NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_domain_audit DISABLE ROW LEVEL SECURITY;

changeSet.sql:
GRANT SELECT, INSERT ON zc_domain_audit TO zc_app;
REVOKE UPDATE, DELETE, TRUNCATE ON zc_domain_audit FROM zc_app;
GRANT USAGE ON SEQUENCE zc_domain_audit_id_seq TO zc_app;
GRANT SELECT, INSERT ON zc_security_event TO zc_app;
REVOKE UPDATE, DELETE, TRUNCATE ON zc_security_event FROM zc_app;
GRANT USAGE ON SEQUENCE zc_security_event_id_seq TO zc_app;

rollback.sql:
REVOKE ALL ON zc_domain_audit FROM zc_app;
REVOKE USAGE ON SEQUENCE zc_domain_audit_id_seq FROM zc_app;
REVOKE ALL ON zc_security_event FROM zc_app;
REVOKE USAGE ON SEQUENCE zc_security_event_id_seq FROM zc_app;
